package glitch

import data.glitch_lib

sensitive_keywords := {"password", "secret", "key", "token", "credential", "passwd", "pwd", "private_key", "public_key", "certificate", "pem", "key_material"}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    contains_sensitive_keyword(attr.name)

    not is_safe_value(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Hard-coded credential detected in IaC script - Avoid embedding sensitive data directly into code. (CWE-798)"
    }
}

